var SanyOperatorsBySymbol = func() map[string]SanyOperatorInfo {
	ops := make(map[string]SanyOperatorInfo, len(SanyCanonicalOperators)+len(SanyOperatorSynonymCanonical))
	for _, op := range SanyCanonicalOperators {
		ops[op.Symbol] = op
	}
	for synonym, canonical := range SanyOperatorSynonymCanonical {
		ops[synonym] = ops[canonical]
	}
	return ops
}()

